package org.nigeriag2p.field;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.Color;import android.text.InputType;import android.view.*;import android.widget.*;import android.security.keystore.KeyGenParameterSpec;import android.security.keystore.KeyProperties;import android.util.Base64;
import android.graphics.Typeface;import android.graphics.drawable.GradientDrawable;import android.location.*;import android.content.pm.PackageManager;import android.net.Uri;import android.text.TextWatcher;import android.text.Editable;import org.json.*;import java.security.*;import javax.crypto.*;import javax.crypto.spec.GCMParameterSpec;import java.net.*;import java.io.*;import java.util.*;

public class MainActivity extends Activity {
 LinearLayout root,body,bar; TextView status; JSONObject record=new JSONObject(); JSONArray records=new JSONArray(); String id="", section="Visit"; Map<String,EditText> inputs=new LinkedHashMap<>(); String key="field-demo-key"; JSONObject catalog; android.location.LocationListener gpsListener; int green=Color.rgb(4,93,70); Handler main=new Handler();
 public void onCreate(Bundle b){super.onCreate(b);loadCatalog();load();UploadJob.schedule(this);home();}
 void set(JSONObject j,String k,Object v){try{j.put(k,v);}catch(Exception e){throw new RuntimeException(e);}} String val(String k){return record.optString(k,"");}
 String endpoint="";void load(){synchronized(FieldStore.LOCK){try{JSONObject all=FieldStore.read(this);records=all.getJSONArray("records");endpoint=all.optString("endpoint","");}catch(Exception e){alert("Storage error","Could not open device storage.");}}}
 void store(){synchronized(FieldStore.LOCK){try{JSONObject all=FieldStore.read(this);FieldStore.mergeSent(all,records);all.put("records",records);all.put("endpoint",endpoint);FieldStore.write(this,all);}catch(Exception e){alert("Storage error","Could not save on this device.");}}}
 void alert(String t,String m){new AlertDialog.Builder(this).setTitle(t).setMessage(m).setPositiveButton("OK",null).show();}
 int dp(float n){return Math.round(n*getResources().getDisplayMetrics().density);}
 GradientDrawable surface(int fill,int stroke,int radius){GradientDrawable d=new GradientDrawable();d.setColor(fill);d.setCornerRadius(dp(radius));if(stroke!=0)d.setStroke(dp(1),stroke);return d;}
 TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(Color.rgb(32,60,53));t.setPadding(0,dp(5),0,dp(5));return t;}
 void screen(String title){cancelLocation();root=new LinearLayout(this);root.setOrientation(1);root.setPadding(dp(16),dp(10),dp(16),dp(8));root.setBackgroundColor(Color.rgb(244,246,243));setContentView(root);LinearLayout brand=new LinearLayout(this);brand.setGravity(Gravity.CENTER_VERTICAL);brand.setOrientation(0);ImageView logo=new ImageView(this);logo.setImageResource(org.nigeriag2p.field.R.drawable.nsipa_logo);logo.setContentDescription("NSIPA National Social Investment Programmes Agency");logo.setScaleType(ImageView.ScaleType.FIT_START);brand.addView(logo,new LinearLayout.LayoutParams(dp(145),dp(58)));TextView badge=text("FIELD  •  DEMO",11);badge.setGravity(Gravity.RIGHT|Gravity.CENTER_VERTICAL);badge.setTextColor(green);badge.setTypeface(Typeface.DEFAULT,Typeface.BOLD);brand.addView(badge,new LinearLayout.LayoutParams(0,-2,1));root.addView(brand);TextView tt=text(title,24);tt.setTypeface(Typeface.create("sans-serif-medium",Typeface.NORMAL));root.addView(tt);TextView warn=text("DEMO ONLY · Fictional records. Supervisor PIN is not staff authentication.",12);warn.setTextColor(Color.rgb(112,77,24));warn.setPadding(dp(12),dp(8),dp(12),dp(8));warn.setBackground(surface(Color.rgb(255,248,233),Color.rgb(227,205,163),8));root.addView(warn);ScrollView scroll=new ScrollView(this);LinearLayout.LayoutParams sp=new LinearLayout.LayoutParams(-1,0,1);sp.topMargin=dp(12);root.addView(scroll,sp);body=new LinearLayout(this);body.setOrientation(1);body.setPadding(dp(14),dp(14),dp(14),dp(14));body.setBackground(surface(Color.WHITE,Color.rgb(221,230,222),12));scroll.setFillViewport(true);scroll.addView(body);status=text("",13);root.addView(status);}
 Button button(LinearLayout parent,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextSize(14);boolean primary=label.startsWith("＋")||label.startsWith("Approve")||label.startsWith("Save")||label.startsWith("Retry");b.setTextColor(primary?Color.WHITE:Color.rgb(40,91,72));b.setBackground(surface(primary?Color.rgb(20,108,85):Color.WHITE,primary?0:Color.rgb(205,219,210),8));b.setPadding(dp(12),dp(9),dp(12),dp(9));b.setMinHeight(dp(48));LinearLayout.LayoutParams bp=new LinearLayout.LayoutParams(-1,-2);bp.topMargin=dp(7);parent.addView(b,bp);b.setOnClickListener(v->action.run());return b;}
 void home(){load();screen("Field workspace");button(body,"＋ New sample visit",()->{record=new JSONObject();id="uuid:"+UUID.randomUUID();set(record,"id",id);set(record,"status","draft");set(record,"date",new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US).format(new Date()));section="Visit";edit();});button(body,"Sync settings",()->settings());body.addView(text("Saved visits",20));if(records.length()==0)body.addView(text("No visits yet. Create a fictional sample.",15));for(int i=0;i<records.length();i++){final int x=i;JSONObject r=records.optJSONObject(i);button(body,r.optString("ref","Unfinished sample")+"  ·  "+r.optString("status"),()->{record=records.optJSONObject(x);id=record.optString("id");section="Visit";if(record.optString("status").equals("draft"))edit();else review();});}}
 void settings(){screen("Connection settings");body.addView(text("Enter an HTTPS ODK Central App User project URL. Use a dedicated test project and form. The URL contains a secret; it is stored encrypted on this device.",15));EditText url=new EditText(this);url.setSingleLine(true);url.setText(endpoint);url.setHint("https://server/v1/key/…/projects/…");body.addView(url);button(body,"Save connection",()->{String s=url.getText().toString().trim();if(!s.startsWith("https://")||!s.contains("/v1/key/")||!s.contains("/projects/")){alert("Invalid URL","Enter a full HTTPS ODK Central App User project URL.");return;}endpoint=s.replaceAll("/+$","");store();UploadJob.schedule(this);home();});button(body,"Back",()->home());}
 void field(String label,String key,int kind){body.addView(text(label,15));EditText e=new EditText(this);e.setSingleLine(true);e.setText(val(key));if(kind==1)e.setInputType(InputType.TYPE_CLASS_NUMBER);if(kind==2)e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED);e.setHint("Sample only");body.addView(e);inputs.put(key,e);}
 void select(String label,String key,String[] options,String[] values){body.addView(text(label,15));Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,options));int sel=0;for(int i=0;i<values.length;i++)if(values[i].equals(val(key)))sel=i;s.setSelection(sel);body.addView(s);s.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){} public void onItemSelected(android.widget.AdapterView<?> a,View v,int p,long i){set(record,key,values[p]);}});}
 void harvest(){String oldLat=val("lat"),oldLon=val("lon");for(Map.Entry<String,EditText> x:inputs.entrySet())set(record,x.getKey(),x.getValue().getText().toString().trim());if(!oldLat.equals(val("lat"))||!oldLon.equals(val("lon")))set(record,"accuracy","");}
 void save(){harvest();boolean found=false;for(int i=0;i<records.length();i++)if(records.optJSONObject(i).optString("id").equals(id)){try{records.put(i,record);}catch(Exception ignored){}found=true;break;}if(!found)records.put(record);store();}
 void edit(){screen("Household visit");body.addView(text("Sections",15));LinearLayout tabs=new LinearLayout(this);tabs.setOrientation(0);body.addView(tabs);for(String name:new String[]{"Visit","Area","Home","Needs","Review"}){Button b=new Button(this);b.setText(name);b.setAllCaps(false);b.setTextSize(11);b.setPadding(0,0,0,0);b.setMinWidth(0);b.setMinHeight(dp(44));b.setTextColor(section.equals(name)?Color.WHITE:Color.rgb(40,91,72));b.setBackground(surface(section.equals(name)?Color.rgb(20,108,85):Color.rgb(237,245,237),0,6));LinearLayout.LayoutParams tabp=new LinearLayout.LayoutParams(0,dp(44),1);tabp.setMargins(dp(2),0,dp(2),0);tabs.addView(b,tabp);b.setOnClickListener(v->{harvest();if(!name.equals("Visit")&&!val("consent").equals("yes")){alert("Consent required","Do not collect household details without consent.");return;}section=name;edit();});}body.addView(text(section,21));inputs.clear();if(section.equals("Visit")){field("Enumerator sample ID","officer",0);field("Visit date (YYYY-MM-DD)","date",0);select("Consent","consent",new String[]{"Select","Yes","No"},new String[]{"","yes","no"});}else if(section.equals("Area")){body.addView(text("Offline area catalogue: Open Admin Data (CC BY 4.0), retrieved 4 Nov 2026. Names require local verification. GPS does not verify the selected area.",14)); place("State / FCT","states","state","");place("Local government area","lgas","lga",val("state_id"));place("Ward","wards","ward",val("lga_id"));body.addView(text("Coordinates (optional)",18));field("Latitude (−90 to 90)","lat",2);field("Longitude (−180 to 180)","lon",2);body.addView(text("Use GPS with permission, or enter coordinates manually. Maps may need internet.",14));button(body,"Use device location",()->{harvest();captureLocation();});button(body,"Open coordinates in Google Maps",()->{harvest();openMap();});}else if(section.equals("Home")){field("Sample reference","ref",0);field("Household members","size",1);field("Children under 18","children",1);select("Shelter","shelter",new String[]{"Select","Owned","Rented","Shared","Other"},new String[]{"","owned","rented","shared","other"});}else if(section.equals("Needs")){select("Livelihood","livelihood",new String[]{"Select","Agriculture","Wage work","Self-employed","None","Other"},new String[]{"","agriculture","wage","self_employed","none","other"});select("Priority need","need",new String[]{"Select","Food","Education","Livelihood","Housing","Other"},new String[]{"","food","education","livelihood","housing","other"});}else {body.addView(text(summary(),16));button(body,"Save and send for supervisor review",()->{harvest();String error=validate();if(!error.isEmpty()){alert("Complete the visit",error);return;}save();review();});}button(body,"Save draft",()->{save();home();});button(body,"Workspace",()->{harvest();home();});}
 String summary(){return "Reference: "+val("ref")+"\nEnumerator: "+val("officer")+"\nDate: "+val("date")+"\nArea: "+val("ward")+", "+val("lga")+", "+val("state")+"\nCoordinates: "+(val("lat").isEmpty()?"Not recorded":val("lat")+", "+val("lon"))+"\nMembers: "+val("size")+"   Children: "+val("children")+"\nShelter: "+val("shelter")+"\nLivelihood: "+val("livelihood")+"\nPriority: "+val("need");}
 String validate(){if(!validPlace("states","state", "")||!validPlace("lgas","lga",val("state_id"))||!validPlace("wards","ward",val("lga_id")))return "Choose a state, LGA and ward from the reference catalogue.";String coordinateError=coordinateError();if(!coordinateError.isEmpty())return coordinateError;for(String k:new String[]{"officer","date","state","lga","ward","ref","size","children","shelter","livelihood","need"})if(val(k).isEmpty())return "All fields are required. Check the Visit, Area, Home and Needs tabs.";if(!val("consent").equals("yes"))return "Consent is required.";try{java.text.SimpleDateFormat f=new java.text.SimpleDateFormat("yyyy-MM-dd",Locale.US);f.setLenient(false);Date d=f.parse(val("date"));if(d.after(new Date()))return "Visit date cannot be in the future.";int n=Integer.parseInt(val("size")),c=Integer.parseInt(val("children"));if(n<1||n>40||c<0||c>n)return "Check the household and children counts.";}catch(Exception e){return "Check the visit date and household counts.";}return "";}
 void review(){screen("Supervisor review");body.addView(text(summary(),16));body.addView(text("Status: "+val("status")+(val("sync_error").isEmpty()?"":" · Last upload: "+val("sync_error")),16));if(val("status").equals("draft")){body.addView(text("Demo supervisor PIN: 246810. This is a test control, not authenticated staff approval.",14));EditText pin=new EditText(this);pin.setHint("Test supervisor PIN");pin.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);body.addView(pin);button(body,"Approve and finalize offline",()->{String err=validate();if(!err.isEmpty()){alert("Cannot approve",err);return;}if(!pin.getText().toString().equals("246810")){alert("Incorrect PIN","Enter the demonstration supervisor PIN.");return;}set(record,"status","approved-demo");set(record,"reviewer","demo-supervisor");save();UploadJob.schedule(this);home();});button(body,"Return to editing",()->{section="Visit";edit();});}else if(val("status").equals("approved-demo")){body.addView(text("Queued for automatic upload when online. Android may delay background work.",14));button(body,"Retry upload",()->sync());}button(body,"Workspace",()->home());}
 String xml(String x){return x.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;").replace("\"","&quot;").replace("'","&apos;");}String tag(String name,String value){return "<"+name+">"+xml(value)+"</"+name+">";}
 String submission(){return "<?xml version=\"1.0\" encoding=\"UTF-8\"?><data id=\"nsipa_field_household_demo\" version=\"2026110401\"><visit>"+tag("enumerator_id",val("officer"))+tag("visit_date",val("date"))+tag("consent","yes")+"</visit><location>"+tag("state",val("state"))+tag("lga",val("lga"))+tag("ward",val("ward"))+(val("lat").isEmpty()?"":tag("coordinates",val("lat")+" "+val("lon")+" 0 "+(val("accuracy").isEmpty()?"0":val("accuracy"))))+"</location><household>"+tag("sample_reference",val("ref"))+tag("household_size",val("size"))+tag("children",val("children"))+tag("shelter",val("shelter"))+"</household><livelihood>"+tag("livelihood_type",val("livelihood"))+tag("priority_needs",val("need"))+"</livelihood><review>"+tag("review_confirmation","yes")+"</review><meta>"+tag("instanceID",val("id"))+tag("instanceName","SAMPLE "+val("ref"))+"</meta></data>";}

 void loadCatalog(){try{InputStream in=getAssets().open("locations.json");ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1)out.write(b,0,n);in.close();catalog=new JSONObject(new String(out.toByteArray(),"UTF-8"));}catch(Exception e){catalog=new JSONObject();}}
 void place(String label,String list,String key,String parent){body.addView(text(label,15));Button b=button(body,val(key).isEmpty()?"Choose "+label:val(key),()->{harvest();if(!key.equals("state")&&parent.isEmpty()){alert("Choose the parent area first","Select the preceding area before continuing.");return;}choosePlace(label,list,key,parent);});b.setAllCaps(false);}
 void choosePlace(String title,String list,String key,String parent){JSONArray data=catalog.optJSONArray(list);if(data==null){alert("Catalogue unavailable","Location catalogue could not be loaded.");return;}ArrayList<JSONObject> choices=new ArrayList<>();for(int i=0;i<data.length();i++){JSONObject item=data.optJSONObject(i);if(parent.isEmpty()||parent.equals(item.optString("parent")))choices.add(item);}Collections.sort(choices,(a,b)->a.optString("name").compareToIgnoreCase(b.optString("name")));LinearLayout box=new LinearLayout(this);box.setOrientation(1);EditText search=new EditText(this);search.setSingleLine(true);search.setHint("Search "+title);box.addView(search);ListView lv=new ListView(this);box.addView(lv,new LinearLayout.LayoutParams(-1,Math.round(350*getResources().getDisplayMetrics().density)));ArrayList<JSONObject> shown=new ArrayList<>(choices);ArrayList<String> names=new ArrayList<>();for(JSONObject i:shown)names.add(i.optString("name"));ArrayAdapter<String> adapter=new ArrayAdapter<>(this,android.R.layout.simple_list_item_1,names);lv.setAdapter(adapter);AlertDialog dialog=new AlertDialog.Builder(this).setTitle(title).setView(box).setNegativeButton("Cancel",null).create();search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int start,int before,int count){shown.clear();names.clear();String q=s.toString().toLowerCase(Locale.ROOT);for(JSONObject i:choices)if(i.optString("name").toLowerCase(Locale.ROOT).contains(q)){shown.add(i);names.add(i.optString("name"));}adapter.notifyDataSetChanged();}public void afterTextChanged(Editable e){}});lv.setOnItemClickListener((a,v,position,ident)->{JSONObject selected=shown.get(position);String old=val(key+"_id"),fresh=selected.optString("id");set(record,key,selected.optString("name"));set(record,key+"_id",fresh);if(!old.equals(fresh)){if(key.equals("state")){set(record,"lga","");set(record,"lga_id","");}if(!key.equals("ward")){set(record,"ward","");set(record,"ward_id","");}}dialog.dismiss();edit();});dialog.show();}
 boolean validPlace(String list,String key,String parent){JSONArray a=catalog.optJSONArray(list);if(a==null||val(key+"_id").isEmpty()||(!key.equals("state")&&parent.isEmpty()))return false;for(int i=0;i<a.length();i++){JSONObject x=a.optJSONObject(i);if(val(key+"_id").equals(x.optString("id"))&&val(key).equals(x.optString("name"))&&(key.equals("state")||parent.equals(x.optString("parent"))))return true;}return false;}
 String coordinateError(){String a=val("lat"),b=val("lon");if(a.isEmpty()&&b.isEmpty())return "";if(a.isEmpty()||b.isEmpty())return "Enter both latitude and longitude.";try{double lat=Double.parseDouble(a),lon=Double.parseDouble(b);if(Double.isNaN(lat)||Double.isNaN(lon)||Math.abs(lat)>90||Math.abs(lon)>180)return "Coordinates are outside the valid latitude/longitude range.";}catch(Exception e){return "Enter valid numeric coordinates.";}return "";}
 void cancelLocation(){if(gpsListener!=null){try{((LocationManager)getSystemService(LOCATION_SERVICE)).removeUpdates(gpsListener);}catch(Exception ignored){}gpsListener=null;}}
 void captureLocation(){cancelLocation();if(checkSelfPermission(android.Manifest.permission.ACCESS_FINE_LOCATION)!=PackageManager.PERMISSION_GRANTED){requestPermissions(new String[]{android.Manifest.permission.ACCESS_FINE_LOCATION},42);return;}LocationManager lm=(LocationManager)getSystemService(LOCATION_SERVICE);if(lm==null||!lm.isProviderEnabled(LocationManager.GPS_PROVIDER)){alert("Location unavailable","Turn on device location / GPS, or enter coordinates manually.");return;}try{status.setText("Waiting for a GPS fix…");gpsListener=new LocationListener(){public void onLocationChanged(Location location){harvest();set(record,"lat",String.format(Locale.US,"%.6f",location.getLatitude()));set(record,"lon",String.format(Locale.US,"%.6f",location.getLongitude()));set(record,"accuracy",location.hasAccuracy()?String.format(Locale.US,"%.1f",location.getAccuracy()):"");try{lm.removeUpdates(this);}catch(SecurityException ignored){}gpsListener=null;if(section.equals("Area"))edit();alert("Location captured","GPS accuracy: "+(location.hasAccuracy()?Math.round(location.getAccuracy())+" m":"not available")+". Check the selected administrative area separately.");}public void onStatusChanged(String p,int s,android.os.Bundle b){}public void onProviderEnabled(String p){}public void onProviderDisabled(String p){}};lm.requestSingleUpdate(LocationManager.GPS_PROVIDER,gpsListener,null);}catch(SecurityException e){alert("Permission needed","Allow location access or enter coordinates manually.");}}
 public void onRequestPermissionsResult(int request,String[] permissions,int[] grants){super.onRequestPermissionsResult(request,permissions,grants);if(request==42){if(grants.length>0&&grants[0]==PackageManager.PERMISSION_GRANTED)captureLocation();else alert("Location permission denied","Enter coordinates manually or grant permission in settings.");}}
 protected void onDestroy(){if(gpsListener!=null){try{((LocationManager)getSystemService(LOCATION_SERVICE)).removeUpdates(gpsListener);}catch(Exception ignored){}}super.onDestroy();}
 void openMap(){String err=coordinateError();if(!err.isEmpty()||val("lat").isEmpty()){alert("Coordinates required",err.isEmpty()?"Capture or enter latitude and longitude first.":err);return;}try{Uri uri=Uri.parse("https://www.google.com/maps/search/?api=1&query="+Uri.encode(val("lat")+","+val("lon")));startActivity(new Intent(Intent.ACTION_VIEW,uri));}catch(Exception e){alert("Maps unavailable","No app is available to open the map link.");}}

 void sync(){if(endpoint.isEmpty()){alert("Connection required","Set the ODK test project App User URL first.");return;}UploadJob.schedule(this);alert("Upload queued","Android will retry approved samples when network access is available. Refresh the workspace to check the status.");}
}
